t.script:
(function () {
  var searchTimeout = null;
  // ... INIT CHIP & DEBOUNCE FUNCTIONS GIỮ NGUYÊN ...
  function initChipInput() {
      var $realInput = $('#real-search-q');
      var $container = $('#chip-container');
      var $visualInput = $('#visual-search-input');
      var currentChips = [];
      var initialVal = $realInput.val();
      if(initialVal) {
          currentChips = initialVal.split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s; });
          renderChips();
      }
      function renderChips() {
          $container.find('.search-chip').remove();
          currentChips.forEach(function(term, index) {
              var $chip = $('<div class="search-chip"><span>' + $('<div>').text(term).html() + '</span><span class="btn-close-chip" data-index="' + index + '">&times;</span></div>');
              $visualInput.before($chip);
          });
          updateRealInput();
      }
      function updateRealInput() { $realInput.val(currentChips.join(', ')); }
      window.addSearchChip = function(term) {
          term = term.trim().replace(/,/g, '');
          if(term && !currentChips.includes(term)) { currentChips.push(term); renderChips(); }
          $visualInput.val(''); $visualInput.focus();
      }
      $container.on('click', '.btn-close-chip', function() {
          currentChips.splice($(this).data('index'), 1); renderChips(); $visualInput.focus();
      });
      $visualInput.on('keydown', function(e) {
          var val = $(this).val();
          if(e.key === 'Backspace' && val === '' && currentChips.length > 0) { currentChips.pop(); renderChips(); }
          else if (e.key === 'Enter') { e.preventDefault(); if (val.trim()) addSearchChip(val); $('#search-form').submit(); }
          else if (e.key === ',') { e.preventDefault(); if (val.trim()) addSearchChip(val); }
      });
      $container.on('click', function(e) { if(e.target === this) $visualInput.focus(); });
  }

  function debounce(func, wait) {
    return function() { clearTimeout(searchTimeout); var context=this, args=arguments; searchTimeout = setTimeout(function() { func.apply(context, args); }, wait); };
  }
  function searchProducts(term, callback) {
    var isComboSearch = $('#comboSearchCheck').is(':checked');
    $.ajax({
      url: "/search_stock/suggest",
      type: "POST", dataType: "json", contentType: "application/json",
      data: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { q: term, combo_search: isComboSearch }, id: new Date().getTime() }),
      success: function(resp) { callback((resp && resp.result && resp.result.products) ? resp.result.products : []); }
    });
  }
  function renderSuggestions(products) {
    var $dropdown = $('#search-suggestions');
    if (!products || products.length === 0) { $dropdown.hide().empty(); return; }
    var html = '';
    products.forEach(function(p) {
       var displayName = p.name || p.default_code || '';
       var imgUrl = p.image_url || '/web/static/img/placeholder.png';
       html += '<div class="suggestion-item border-bottom p-2" data-name="' + displayName + '" style="cursor:pointer;">';
       html += '  <div class="d-flex align-items-center">';
       html += '    <img src="' + imgUrl + '" class="rounded border me-2 flex-shrink-0" style="width:40px; height:40px; object-fit:cover;"/>';
       html += '    <div class="flex-grow-1 overflow-hidden">';
       html += '      <div class="fw-bold text-dark text-truncate" style="font-size:0.9rem;">' + (p.default_code || '') + '</div>';
       html += '      <div class="text-muted text-truncate small">' + (p.name || '') + '</div>';
       html += '    </div>';
       html += '    <div class="ms-2 text-primary"><i class="fa fa-angle-right"></i></div>';
       html += '  </div></div>';
    });
    $dropdown.html(html).show();
  }

  $(document).ready(function() {
    initChipInput(); 
    var $visualInput = $('#visual-search-input');
    var $dropdown = $('#search-suggestions');
    $visualInput.on('input', debounce(function() {
      var term = $(this).val().trim();
      if (term.length >= 2) searchProducts(term, renderSuggestions);
      else $dropdown.hide();
    }, 300));
    $(document).on('click', '.suggestion-item', function() {
      var name = $(this).data('name');
      if (name) { window.addSearchChip(name); $dropdown.hide(); $('#search-form').submit(); }
    });
    $(document).on('click', function(e) { if (!$(e.target).closest('#chip-container, #search-suggestions').length) $dropdown.hide(); });

    // --- XỬ LÝ EXPAND ROW ---
    $(document).on('click', '.btn-expand', function () {
       var $btn = $(this);
       var pid = $btn.data('pid');
       var isCombo = String($btn.data('is-combo')) === 'true';
       var $row = $btn.closest('tr'); 
       var $next = $row.next();

       if ($next.length && $next.hasClass('detail-row') && $next.is(':visible')) { $next.remove(); $btn.html('<i class="fa fa-plus"></i>'); return; }

       var colCount = $row.children('td').length;
       var $detail = $('<tr class="detail-row"><td colspan="' + colCount + '"><div class="p-3 bg-light text-center"><span class="spinner-border spinner-border-sm me-2"></span>Đang tải...</div></td></tr>');
       $row.after($detail);
       $btn.html('<i class="fa fa-minus"></i>');

       var currentWid = $('select[name="warehouse_id"]').val() || '';
       var detailMode = isCombo ? 'per_warehouse' : null;

       $.ajax({
          url: "/search_stock/product_breakdown",
          type: "POST", dataType: "json", contentType: "application/json",
          data: JSON.stringify({jsonrpc: "2.0", method: "call", params: { product_id: pid, warehouse_id: currentWid, detail_mode: detailMode }, id: 1}),
          success: function(resp) {
              var res = (resp && resp.result) ? resp.result : {};
              if(res.ok) {
                  $detail.find('td').html(buildDetailTable(res));
              } else {
                  $detail.find('td').html('<div class="text-danger small p-3">Lỗi: ' + (res.error || 'Unknown') + '</div>');
              }
          }
       });
    });

    // >>> TỰ ĐỘNG BUNG HẾT DÒNG KHI LOAD TRANG <<<
    $('.btn-expand').trigger('click');
  });

  function fmt(n) { return (parseFloat(n)||0).toLocaleString('en-US'); }

  function buildDetailTable(data) {
      var html = '';
      var rows = data.rows || [];

      // CASE 1: COMBO
      if(data.mode === 'components_by_warehouse') {
          html += '<div class="p-3 detail-container-mobile"><div class="row g-3">';
          rows.forEach(function(c){
              var imgUrl = c.image_url || '/web/static/img/placeholder.png';
              html += '<div class="col-12 col-md-12">';
              html += '  <div class="card h-100 border shadow-sm">';
              html += '    <div class="card-header bg-white d-flex align-items-center py-2">';
              html += '      <img src="' + imgUrl + '" class="rounded border me-3" style="width:40px; height:40px; object-fit:contain;">';
              html += '      <div class="flex-grow-1">';
              html += '        <div class="fw-bold text-primary">' + c.name + '</div>';
              html += '        <div class="small text-muted">SL Combo: <b>' + fmt(c.component_qty_in_combo) + '</b></div>';
              html += '      </div>';
              html += '    </div>';
              html += '    <div class="card-body p-0">';
              (c.warehouses||[]).forEach(function(w){
                  html += '<div class="border-bottom p-2">';
                  html += '  <div class="fw-bold small mb-1">' + w.warehouse_name + '</div>';
                  html += '  <div class="d-flex">';
                  html += '    <div class="flex-fill text-center border-end"><div class="small text-muted">Sẵn sàng</div><div class="fw-bold text-success">' + fmt(w.qty_available) + '</div></div>';
                  html += '    <div class="flex-fill text-center"><div class="small text-muted">Thực tế</div><div>' + fmt(w.qty_total) + '</div></div>';
                  html += '  </div>';
                  html += '</div>';
              });
              html += '    </div></div></div>';
          });
          html += '</div></div>';
      } 

      // CASE 2: SẢN PHẨM THƯỜNG
      else {
          html += '<div class="detail-container-mobile">';
          html += '<div class="d-none d-md-block p-3 bg-white border rounded">';
          html += '<table class="table table-sm mb-0"><thead><tr><th>Kho hàng</th><th class="text-end">Tồn</th><th class="text-end">Giữ</th><th class="text-end">Sẵn sàng</th></tr></thead><tbody>';
          rows.forEach(function(r){
              var availClass = (r.qty_available > 0) ? 'text-success fw-bold' : 'text-muted';
              html += '<tr><td>' + r.warehouse_name + '</td><td class="text-end">' + fmt(r.qty_total) + '</td><td class="text-end">' + fmt(r.qty_reserved) + '</td><td class="text-end ' + availClass + '">' + fmt(r.qty_available) + '</td></tr>';
          });
          html += '</tbody></table></div>';

          html += '<div class="d-md-none">';
          rows.forEach(function(r){
               html += '<div class="wh-card">';
               html += '  <div class="wh-header">' + r.warehouse_name + '</div>';
               html += '  <div class="wh-stats">';
               html += '    <div class="wh-stat-col ' + (r.qty_total==0 ? 'dim':'') + '"><div class="wh-label">Tổng</div><div class="wh-val">' + fmt(r.qty_total) + '</div></div>';
               html += '    <div class="wh-stat-col ' + (r.qty_reserved==0 ? 'dim':'') + '"><div class="wh-label">Đã giữ</div><div class="wh-val text-muted">' + fmt(r.qty_reserved) + '</div></div>';
               html += '    <div class="wh-stat-col highlight"><div class="wh-label">Có thể bán</div><div class="wh-val">' + fmt(r.qty_available) + '</div></div>';
               html += '  </div>';
               html += '</div>';
          });
          html += '</div>';
          html += '</div>';
      }

      return html;
  }

})();
